<?php require __DIR__.'/bootstrap.php';require __DIR__.'/bootstrap_auth.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT * FROM tours WHERE id=?");$q->execute([$id]);$t=$q->fetch();if(!$t)redirect('tour_manage.php');
